const crypto = require('crypto');

const token = $json.body?.sessionToken;

const validFormat =
  typeof token === 'string' &&
  /^[a-f0-9]{64}$/.test(token);

return {
  json: {
    sessionHash: validFormat
      ? crypto.createHash('sha256')
          .update(token)
          .digest('hex')
      : null
  }
};

