const session =
  $('Verifiko sesionin e agjentit')
    .first().json.session;

const record = $json;
const fields = record.fields ?? record;

const text = value =>
  String(value ?? '').trim();

const savedEmail =
  text(fields.Email).toLowerCase();

const status =
  text(fields.Statusi).toUpperCase();

const isClient = session.role === 'CLIENT';

const profileAllowed =
  record.id === session.actor_id &&
  savedEmail === text(session.email).toLowerCase() &&
  (
    isClient
      ? ['AKTIV', 'GUEST'].includes(status)
      : ['I LIRË', 'I ZËNË', 'NË UDHËTIM', 'OFFLINE']
          .includes(status)
  );

const recordIds = value =>
  Array.isArray(value)
    ? [...new Set(value.filter(id =>
        typeof id === 'string' &&
        /^rec[a-zA-Z0-9]{14}$/.test(id)
      ))]
    : [];

const profile = profileAllowed
  ? {
      name: text(
        fields[isClient
          ? 'Emri i klientit'
          : 'Emri i plotë']
      ),
      phone: text(fields['Numri i telefonit']),
      status,
      ...(isClient
        ? {
            totalTrips:
              Number(fields['Numri total i udhëtimeve']) || 0
          }
        : {
            city: text(fields.Qyteti),
            car: text(fields.Makina),
            plate: text(fields.Targa)
          })
    }
  : null;

return {
  json: {
    profileAllowed,
    actorId: session.actor_id,
    role: session.role,
    profile,
    tripIds: profileAllowed
      ? recordIds(fields['Udhëtimet'])
      : [],
    assignmentIds: profileAllowed && !isClient
      ? recordIds(fields['Caktimet'])
      : []
  }
};

const context =
  $('Kontrollo profilin e agjentit').first().json;

const ids = context.role === 'DRIVER'
  ? context.assignmentIds
  : [];

const groups = [];

for (let i = 0; i < ids.length; i += 50) {
  groups.push(ids.slice(i, i + 50));
}

if (groups.length === 0) groups.push([]);

return groups.map(group => ({
  json: {
    filterFormula: group.length
      ? 'OR(' + group.map(id =>
          'RECORD_ID()=' + JSON.stringify(id)
        ).join(',') + ')'
      : 'FALSE()'
  }
}));

const context =
  $('Kontrollo profilin e agjentit').first().json;

const allowedIds = new Set(context.assignmentIds);

const text = value => String(value ?? '').trim();

const assignments = context.role === 'DRIVER'
  ? $input.all().flatMap(item => {
      const record = item.json;
      const fields = record.fields ?? record;

      const trips = Array.isArray(fields['Udhëtimi'])
        ? fields['Udhëtimi'].filter(id =>
            typeof id === 'string' &&
            /^rec[a-zA-Z0-9]{14}$/.test(id)
          )
        : [];

      const belongsToDriver =
        allowedIds.has(record.id) &&
        Array.isArray(fields['Shoferi']) &&
        fields['Shoferi'].includes(context.actorId) &&
        trips.length === 1;

      if (!belongsToDriver) return [];

      return [{
        recordId: record.id,
        assignmentId: text(fields['Caktimi']),
        tripId: trips[0],
        decision: text(fields['Vendimi']).toUpperCase(),
        assignedAt: text(fields['Data e caktimit'])
      }];
    })
  : [];

const tripIds = [...new Set([
  ...context.tripIds,
  ...assignments.map(a => a.tripId)
])];

return [{
  json: {
    ...context,
    assignments,
    tripIds
  }
}];

const context =
  $('Përmblidh caktimet e agjentit').first().json;

const groups = [];

for (let i = 0; i < context.tripIds.length; i += 50) {
  groups.push(context.tripIds.slice(i, i + 50));
}

if (groups.length === 0) groups.push([]);

return groups.map(group => ({
  json: {
    filterFormula: group.length
      ? 'OR(' + group.map(id =>
          'RECORD_ID()=' + JSON.stringify(id)
        ).join(',') + ')'
      : 'FALSE()'
  }
}));

const context =
  $('Përmblidh caktimet e agjentit').first().json;

const isClient = context.role === 'CLIENT';
const allowedIds = new Set(context.tripIds);
const seen = new Set();

const text = value => String(value ?? '').trim();
const validId = value =>
  typeof value === 'string' &&
  /^rec[a-zA-Z0-9]{14}$/.test(value);

const trips = [];

for (const item of $input.all()) {
  const record = item.json;
  const fields = record.fields ?? record;

  if (!allowedIds.has(record.id) || seen.has(record.id)) {
    continue;
  }

  const ownLinks = fields[
    isClient ? 'Klienti' : 'Shoferi'
  ];

  const ownsTrip =
    Array.isArray(ownLinks) &&
    ownLinks.includes(context.actorId);

  const audits = context.assignments
    .filter(a => a.tripId === record.id)
    .sort((a, b) =>
      (Date.parse(b.assignedAt) || 0) -
      (Date.parse(a.assignedAt) || 0)
    );

  if (!ownsTrip) {
    if (isClient || audits.length === 0) continue;

    trips.push({
      id: record.id,
      number: fields['Udhëtimi'] || record.id,
      status: audits[0].decision === 'REFUZO'
        ? 'REFUZUAR'
        : null,
      ownDecision: audits[0].decision,
      assignedAt: audits[0].assignedAt,
      historicalOnly: true,
      contactId: null
    });

    seen.add(record.id);
    continue;
  }

  const contacts = fields[
    isClient ? 'Shoferi' : 'Klienti'
  ];

  const contactId =
    Array.isArray(contacts) &&
    contacts.length === 1 &&
    validId(contacts[0])
      ? contacts[0]
      : null;

  trips.push({
    id: record.id,
    number: fields['Udhëtimi'] || record.id,
    status: text(fields.Statusi).toUpperCase(),
    city: text(fields.Qyteti),
    pickup: text(fields['Lokacioni i marrjes']),
    destination: text(fields.Destinacioni),
    requestedAt: text(fields['Data e kërkesës']) || null,
    startedAt: text(fields['Data e fillimit']) || null,
    finishedAt: text(fields['Data e përfundimit']) || null,
    price: typeof fields['Çmimi'] === 'number'
      ? fields['Çmimi']
      : null,
    assignedAt: audits[0]?.assignedAt ?? null,
    ownDecision: audits[0]?.decision ?? null,
    historicalOnly: false,
    contactId
  });

  seen.add(record.id);
}

const contactIds = [...new Set(
  trips.map(t => t.contactId).filter(validId)
)];

const groups = [];

for (let i = 0; i < contactIds.length; i += 50) {
  groups.push(contactIds.slice(i, i + 50));
}

if (groups.length === 0) groups.push([]);

return groups.map(group => ({
  json: {
    ...context,
    trips,
    contactTableId: isClient
      ? 'tblQtDtElgjUllUtA'
      : 'tblubVmdPPIaPsbsM',
    filterFormula: group.length
      ? 'OR(' + group.map(id =>
          'RECORD_ID()=' + JSON.stringify(id)
        ).join(',') + ')'
      : 'FALSE()'
  }
}));

const context =
  $('Përgatit kontaktet e udhëtimeve').first().json;

const isClient = context.role === 'CLIENT';
const text = value => String(value ?? '').trim();

const allowedContacts = new Set(
  context.trips.map(t => t.contactId).filter(Boolean)
);

const contacts = new Map();

for (const item of $input.all()) {
  const record = item.json;
  if (!allowedContacts.has(record.id)) continue;

  const fields = record.fields ?? record;

  contacts.set(record.id, isClient
    ? {
        name: text(fields['Emri i plotë']),
        phone: text(fields['Numri i telefonit']),
        car: text(fields.Makina),
        plate: text(fields.Targa)
      }
    : {
        name: text(fields['Emri i klientit']),
        phone: text(fields['Numri i telefonit'])
      }
  );
}

const trips = context.trips.map(trip => {
  const { contactId, ...details } = trip;
  const contact = contacts.get(contactId) ?? null;

  return {
    ...details,
    ...(isClient
      ? { driver: contact }
      : { customer: contact })
  };
});

const timezone = 'Europe/Belgrade';

const formatter = new Intl.DateTimeFormat('en-CA', {
  timeZone: timezone,
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
});

const dayKey = value => {
  if (!value) return null;

  const date = new Date(value);
  if (!Number.isFinite(date.getTime())) return null;

  const parts = Object.fromEntries(
    formatter.formatToParts(date)
      .map(part => [part.type, part.value])
  );

  return `${parts.year}-${parts.month}-${parts.day}`;
};

const checkedAt = new Date().toISOString();
const today = dayKey(checkedAt);
const time = value => Date.parse(value) || 0;

const activeTrips = trips.filter(trip =>
  !trip.historicalOnly &&
  ['KËRKUAR', 'CAKTUAR', 'PRANUAR', 'NË UDHËTIM']
    .includes(trip.status)
);

const completedTrips = trips
  .filter(trip =>
    !trip.historicalOnly &&
    trip.status === 'PËRFUNDUAR'
  )
  .sort((a, b) =>
    time(b.finishedAt) - time(a.finishedAt)
  );

const recentTrips = [...trips]
  .sort((a, b) =>
    time(b.requestedAt || b.assignedAt || b.finishedAt) -
    time(a.requestedAt || a.assignedAt || a.finishedAt)
  )
  .slice(0, 10);

const tripNumbers = new Map(
  trips.map(trip => [trip.id, trip.number])
);

const refusedAssignments = isClient
  ? []
  : context.assignments
      .filter(a => a.decision === 'REFUZO')
      .map(a => ({
        assignmentId: a.assignmentId,
        tripId: a.tripId,
        tripNumber: tripNumbers.get(a.tripId) ?? null,
        assignedAt: a.assignedAt,
        decision: a.decision
      }))
      .sort((a, b) =>
        time(b.assignedAt) - time(a.assignedAt)
      );

const stats = {
  totalCompletedTrips: isClient
    ? context.profile.totalTrips
    : completedTrips.length,
  activeTripsCount: activeTrips.length,
  completedToday: completedTrips.filter(trip =>
    dayKey(trip.finishedAt) === today
  ).length
};

if (!isClient) {
  stats.assignedToday = new Set(
    context.assignments
      .filter(a => dayKey(a.assignedAt) === today)
      .map(a => a.tripId)
  ).size;

  stats.refusedTripsCount = new Set(
    refusedAssignments.map(a => a.tripId)
  ).size;
}

return [{
  json: {
    ok: true,
    role: context.role,
    checkedAt,
    timezone,
    today,
    profile: context.profile,
    stats,
    trips,
    activeTrips,
    currentTrip: activeTrips.find(trip =>
      trip.status === 'NË UDHËTIM'
    ) ?? null,
    nextTrip: [...activeTrips]
      .filter(trip =>
        ['CAKTUAR', 'PRANUAR'].includes(trip.status)
      )
      .sort((a, b) =>
        time(a.requestedAt) - time(b.requestedAt)
      )[0] ?? null,
    recentTrips,
    completedTrips,
    refusedAssignments
  }
}];
